from pathlib import Pathfrom typing import Dict, Optional, Unionimport loggingimport pandas as pdfrom . core import TxInOut, SWATOutputManager, HRUManagerfrom . io import HRUWriter, SWATParam, HRURead, FileCIOfrom . run import SWATRunlogger = logging.getLogger(__name__)class SWATProject:    """        >>> project = SWATProject(        ...     project_dir="D:/SWAT/my_project",        ...     swat_exe="D:/SWAT/swat2012.exe"        ... )        >>> project.update_parameters({'CN2': 75})        >>> project.run()        >>> df = project.output.read_reach()    """    def __init__(            self,            txinout_dir: Union[str, Path],            swat_exe:    Union[str, Path],            param_file:  Optional[str] = None    ):        self.txinout        = TxInOut(str(txinout_dir))        self.param_file     = SWATParam(param_file)        self.swat_exe       = SWATRun(swat_exe)        # ==========================================        self.hru_manager     = HRUManager(self.txinout, self.param_file)        self.file_cio        = FileCIO(self.txinout)        self._output_manager = None        self._observed_data  = {}        self._analysis       = None        self._visualization  = None        logger.info(f"SWAT Project initialized: {self.txinout}")        logger.info(f"Found {self.txinout.number_hru} HRUs in {self.txinout.number_sub} subbasins")    # ================ Read data =============================    def read_param_values(self, param: list):        return self.hru_manager.read_param_values(param)    def run(self):        return self.swat_exe.run(self.txinout.directory)    def info(self):        """Print project information"""        print(f"TxtInOut: {self.txinout.directory}")        print("=" * 20)        print(f"SWAT Executable: {self.swat_exe}")        self.txinout.info()        print(f"Observed Datasets: {len(self._observed_data)}")        if self._observed_data:            for name in self._observed_data.keys():                print(f"  - {name}")        print("=" * 20)    def __repr__(self):        return (f"SWATProject '{self.txinout.directory}')', "                f"\n hrs={self.txinout.number_hru}, "                f"\n subs={self.txinout.number_sub})")